    impl<'de> Deserialize<'de> for ProductName {
        fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
        where
            D: Deserializer<'de>,
        {
            Self::parse(String::deserialize(deserializer)?).map_err(serde::de::Error::custom)
        }
    }

    #[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, JsonSchema)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    pub(super) struct ProductReleaseId {
        product: ProductName,
        version: Version,
    }

    #[derive(Deserialize)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    struct ProductReleaseIdWire {
        product: ProductName,
        version: Version,
    }

    impl ProductReleaseId {
        fn new(product: ProductName, version: Version) -> Result<Self, SuccessorError> {
            if version.grammar() != VersionGrammar::SemVer {
                return Err(SuccessorError::NonSemverProductVersion {
                    version: Box::new(version),
                });
            }
            Ok(Self { product, version })
        }

        fn from_coordinated_versions(
            product: ProductName,
            versions: impl IntoIterator<Item = Version>,
        ) -> Result<Self, SuccessorError> {
            let mut versions = versions.into_iter();
            let Some(version) = versions.next() else {
                return Err(SuccessorError::EmptyCoordinatedRoster);
            };
            let release = Self::new(product, version.clone())?;
            for candidate in versions {
                if candidate.grammar() != VersionGrammar::SemVer {
                    return Err(SuccessorError::NonSemverProductVersion {
                        version: Box::new(candidate),
                    });
                }
                if candidate != version {
                    return Err(SuccessorError::DivergentCoordinatedVersion {
                        expected: Box::new(version),
                        found: Box::new(candidate),
                    });
                }
            }
            Ok(release)
        }

        fn tag(&self) -> String {
            format!("{}@{}", self.product, self.version.render())
        }
    }

    impl PartialOrd for ProductReleaseId {
        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
            Some(self.cmp(other))
        }
    }

    impl Ord for ProductReleaseId {
        fn cmp(&self, other: &Self) -> Ordering {
            (&self.product, version_ord_key(&self.version)).cmp(&(&other.product, version_ord_key(&other.version)))
        }
    }

    impl<'de> Deserialize<'de> for ProductReleaseId {
        fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
        where
            D: Deserializer<'de>,
        {
            let wire = ProductReleaseIdWire::deserialize(deserializer)?;
            Self::new(wire.product, wire.version).map_err(serde::de::Error::custom)
        }
    }

